use vstd::prelude::*;

verus! {

// Specification function to check if an index holds the maximum value
spec fn is_max_index(a: Seq<i32>, idx: int) -> bool {
    0 <= idx < a.len() &&
    forall|i: int| 0 <= i < a.len() ==> a[i] <= a[idx]
}

fn find_max(a: &[i32]) -> (result: usize)
    requires
        a.len() > 0,
    ensures
        result < a.len(),
        is_max_index(a@, result as int),
{
    // Initialize max_index to 0 assuming the array is non-empty
    let mut max_index = 0;

    // Iterate over the array, starting from index 1
    for i in 1..a.len()
        invariant
            a.len() > 0,
            max_index < a.len(),
            // max_index holds the maximum value among elements [0..i)
            forall|j: int| 0 <= j < i ==> a[j] <= a[max_index],
    {
        if a[i] > a[max_index] {
            max_index = i;
        }
    }

    // After the loop, max_index holds the maximum among all elements
    assert(forall|j: int| 0 <= j < a.len() ==> a[j] <= a[max_index]);
    
    max_index
}

} // verus!